const storeCtx = $('Validate & Route1').first().json;

if (!storeCtx.store_id) return [];

const files = $input.first().json.files || [];
const batchFolders = files.filter(f => !f.name.endsWith('_done'));

if (batchFolders.length === 0) return [];

return batchFolders.map(folder => ({
  json: {
    store_id: storeCtx.store_id,
    batch_folder_id: folder.id,
    batch_folder_name: folder.name,
    drive_folder_id: storeCtx.drive_folder_id,
    default_status: storeCtx.default_status
  }
}));

const batchCtx = $('Filter Batch Folders').item.json;
const files = $input.first().json.files || [];
const productFolders = files.filter(f => !f.name.endsWith('_done'));

if (productFolders.length === 0) return [];

return productFolders.map(folder => ({
  json: {
    store_id: batchCtx.store_id,
    folder_id: folder.id,
    folder_name: folder.name,
    drive_folder_id: batchCtx.drive_folder_id,
    default_status: batchCtx.default_status
  }
}));

const files = $input.item.json.files;
const ctx = $('Claim One Row').item.json;

const txtFile = files.find(f =>
  f.name?.endsWith('.txt') ||
  f.mimeType === 'application/vnd.google-apps.document' ||
  f.mimeType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
);

const imageFiles = files.filter(f => f.mimeType?.startsWith('image/'));

if (!txtFile) {
  throw new Error(`No text/doc file found in folder ${ctx.folder_name}. Files: ${files.map(f => f.name).join(', ')}`);
}
if (imageFiles.length === 0) {
  throw new Error(`No image files found in folder ${ctx.folder_name}. Files: ${files.map(f => f.name).join(', ')}`);
}

const cleanName = txtFile.name.replace(/\.docx$/i, '');

return [{
  json: {
    queue_id: ctx.id,
    store_id: ctx.store_id,
    folderId: ctx.folder_id,
    folderName: ctx.folder_name,
    drive_folder_id: ctx.drive_folder_id,
    default_status: ctx.default_status,
    txtFileId: txtFile.id,
    txtFileName: cleanName,
    txtMimeType: txtFile.mimeType,
    imageFiles: imageFiles.map(f => ({ id: f.id, name: f.name, mimeType: f.mimeType }))
  }
}];

const items = $input.all();
if (items.length === 0 || !items[0].json.id) return [];
return items;

// === Parse Unified Product LLM JSON ===
function repairTruncatedJson(str) {
  const boundaryChars = new Set([',', '{', '[', '}', ']']);

  for (let end = str.length; end > 0; end--) {
    if (end < str.length && !boundaryChars.has(str[end - 1])) continue;

    let candidate = str.slice(0, end).trimEnd();
    candidate = candidate.replace(/,+$/, '');
    candidate = candidate.replace(/,?\s*"[^"]*"\s*:\s*$/, '');

    const quoteCount = (candidate.match(/(?<!\\)"/g) || []).length;
    if (quoteCount % 2 !== 0) candidate += '"';

    candidate = candidate.replace(/,\s*$/, '');

    const stack = [];
    let inStr = false, esc = false;
    for (const ch of candidate) {
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (ch === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (ch === '{' || ch === '[') stack.push(ch);
      else if (ch === '}' && stack[stack.length - 1] === '{') stack.pop();
      else if (ch === ']' && stack[stack.length - 1] === '[') stack.pop();
    }
    let closer = '';
    for (let i = stack.length - 1; i >= 0; i--) closer += stack[i] === '{' ? '}' : ']';

    try {
      return JSON.parse(candidate + closer);
    } catch (e) {
      continue;
    }
  }
  return null;
}

// 1. Grab raw text from the single LLM Chain
const raw = $input.first().json.text || $input.first().json.output || $input.first().json.content || '';

// 2. Extract JSON object (ignoring any markdown wrappers like ```json ... ```)
const jsonMatch = raw.match(/\{[\s\S]*\}/);

let parsed = null;
if (jsonMatch) {
  try {
    parsed = JSON.parse(jsonMatch[0]);
  } catch (e) {
    console.warn('Unified LLM chain: direct parse failed, attempting repair:', e.message);
    parsed = repairTruncatedJson(jsonMatch[0]);
  }
}

if (!parsed) {
  throw new Error('Unified LLM chain: JSON parsing failed after repair attempt. Raw: ' + raw.substring(0, 300));
}

// 3. Clean up Tags (handle both Array and comma-separated string)
let tagsArray = [];
if (Array.isArray(parsed.tags)) {
  tagsArray = parsed.tags;
} else if (typeof parsed.tags === 'string' && parsed.tags.trim() !== '') {
  tagsArray = parsed.tags.split(',').map(t => t.trim());
}

// 4. Clean up Categories (ensure it is wrapped in an array)
let categoriesArray = [];
if (Array.isArray(parsed.categories)) {
  categoriesArray = parsed.categories;
} else if (typeof parsed.categories === 'string' && parsed.categories.trim() !== '') {
  categoriesArray = [parsed.categories.trim()];
}

// 5. Fallback logic for Title, Permalink & Short Description
const title = parsed.title || 'Untitled Product';
const permalink = parsed.permalink || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const shortDescription = parsed.short_description || title;

// 6. Return the unified product object
return [{
  json: {
    title: title,
    description: parsed.description || '',
    short_description: shortDescription,
    permalink: permalink,
    categories: categoriesArray,
    tags: tagsArray,
    price: parsed.price || null,
    attributes: parsed.attributes || []
  }
}];

const item = $input.item;
const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, 'image');

return {
  json: {
    ...item.json,
    files: [{
      filename: item.json.imageFileName,
      mimeType: item.json.imageMimeType,
      base64_data: buffer.toString('base64')
    }]
  }
};

const ctx = $('Check Both Files Exist').item.json;
const product = $input.first().json;

const imageFiles = ctx.imageFiles;
if (!imageFiles || imageFiles.length === 0) {
  throw new Error('No imageFiles found in context for folder ' + ctx.folderName);
}

return imageFiles.map(img => ({
  json: {
    title: product.title,
    description: product.description,
    short_description: product.short_description,
    permalink: product.permalink,
    categories: product.categories,
    attributes: product.attributes,
    tags: product.tags,
    price: product.price,
    imageFileId: img.id,
    imageFileName: img.name,
    imageMimeType: img.mimeType,
    queue_id: ctx.queue_id,
    folderId: ctx.folderId,
    folderName: ctx.folderName,
    store_id: ctx.store_id,
    drive_folder_id: ctx.drive_folder_id,
    default_status: ctx.default_status
  }
}));
